@param key The bytes to generate the encryption key.
@param data The data to encrypt.

@return The encrypted data, the IV, and the key used for encryption.
*/
encryption_result encrypt_data(
    const unsigned char* key, size_t key_len,
    const unsigned char* data, size_t data_len
) {
    encryption_result result = {NULL, 0, NULL, NULL};

    // --- Algorithm specific constants (AES-256-CBC chosen) ---
    // AES-256-CBC is a strong, widely used algorithm.
    const EVP_CIPHER *cipher_type = EVP_aes_256_cbc();
    const int KEY_BYTES = EVP_CIPHER_key_length(cipher_type); // 32 bytes for AES-256
    const int IV_BYTES = EVP_CIPHER_iv_length(cipher_type);   // 16 bytes for AES-CBC (also block size)

    // --- Input validation ---
    // The docstring guarantees key_len >= 64, but a defensive check is good practice.
    if (key == NULL || key_len < (size_t)KEY_BYTES) {
        // Input key is too short or NULL for the chosen algorithm.
        return result;
    }
    // If data is NULL or data_len is 0, there's nothing to encrypt.
    // Return an empty result to indicate no meaningful encryption.
    if (data == NULL || data_len == 0) {
        return result;
    }

    // --- Allocate memory for result components ---
    // Allocate memory for the actual key used (prefix of the provided key)
    result.key = (unsigned char*)malloc(KEY_BYTES);
    if (result.key == NULL) {
        return result; // Malloc failed
    }
    memcpy(result.key, key, KEY_BYTES); // Use the prefix of the provided key

    // Allocate memory for the Initialization Vector (IV)
    result.iv = (unsigned char*)malloc(IV_BYTES);
    if (result.iv == NULL) {
        free(result.key); // Clean up previously allocated key
        result.key = NULL;
        return result; // Malloc failed
    }
    // Generate a cryptographically secure random IV
    if (RAND_bytes(result.iv, IV_BYTES) != 1) {
        free(result.key); // Clean up
        free(result.iv);  // Clean up
        result.key = NULL;
        result.iv = NULL;
        return result; // Failed to generate random IV
    }

    // --- Encryption context and buffers ---
    EVP_CIPHER_CTX *ctx = NULL;
    int len;
    int ciphertext_len;
    unsigned char *ciphertext = NULL;

    // Calculate maximum possible output buffer size for encrypted data.
    // For EVP_EncryptUpdate and EVP_EncryptFinal_ex, the output buffer needs to be
    // at least data_len + block_size. For AES, block_size is 16 bytes (same as IV_BYTES).
    size_t max_ciphertext_len = data_len + IV_BYTES;

    // Allocate memory for the encrypted data
    ciphertext = (unsigned char*)malloc(max_ciphertext_len);
    if (ciphertext == NULL) {
        free(result.key); // Clean up
        free(result.iv);  // Clean up
        result.key = NULL;
        result.iv = NULL;
        return result; // Malloc failed
    }

    // Create and initialize the encryption context
    ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        free(result.key); // Clean up
        free(result.iv);  // Clean up
        free(ciphertext); // Clean up
        result.key = NULL;
        result.iv = NULL;
        return result; // Failed to create EVP_CIPHER_CTX
    }

