        EVP_CIPHER_CTX_free(ctx); // Clean up context
        free(result.key);         // Clean up
        free(result.iv);          // Clean up
        free(ciphertext);         // Clean up
        result.key = NULL;
        result.iv = NULL;
        return result; // Encryption initialization failed
    }

    // Provide the message to be encrypted, and obtain the encrypted output.
    // EVP_EncryptUpdate can be called multiple times if data is large.
    if (1 != EVP_EncryptUpdate(ctx, ciphertext, &len, data, data_len)) {
        EVP_CIPHER_CTX_free(ctx); // Clean up context
        free(result.key);         // Clean up
        free(result.iv);          // Clean up
        free(ciphertext);         // Clean up
        result.key = NULL;
        result.iv = NULL;
        return result; // Encryption update failed
    }
    ciphertext_len = len;

    // Finalize the encryption. This handles any remaining data and padding.
    if (1 != EVP_EncryptFinal_ex(ctx, ciphertext + len, &len)) {
        EVP_CIPHER_CTX_free(ctx); // Clean up context
        free(result.key);         // Clean up
        free(result.iv);          // Clean up
        free(ciphertext);         // Clean up
        result.key = NULL;
        result.iv = NULL;
        return result; // Encryption finalization failed
    }
    ciphertext_len += len;

    // --- Clean up context and assign results ---
    EVP_CIPHER_CTX_free(ctx); // Free the encryption context

    result.encrypted_data = ciphertext;
    result.encrypted_len = (size_t)ciphertext_len;

    return result;
}
